// Acceptance: deploy gate auto-promotes when production is already migrated.
//
// When migrations were applied manually (db-migrate, target production) but the
// live Worker still serves an older commit, the automatic promotion must clear
// once the live production ledger holds every target web migration. The gate
// proves this by set inclusion through the production /up body, not only the
// live Worker's journal file, and never by high-water mark: a max would let a
// newer bot row mask a missing web migration.
//
// Contract pinned here (Builder implements it; do not edit this file):
// - /up exposes `migration_ledger`: the sorted applied `created_at` set from
//   drizzle.__drizzle_migrations, or null when the database read fails (an
//   empty ledger is `[]`, not null).
// - `--check-migrations` clears (exit 0) when every target web entry's `when`
//   is a member of `migration_ledger` with `db: "ok"` and
//   `pending_migrations: 0`, for automatic and manual triggers alike, without
//   requiring operator confirmation. Extra ledger values are harmless.
// - It halts (exit 1) when the target has web migrations the ledger lacks,
//   naming the pending tags — even when a newer foreign row is present — and
//   when the ledger read fails (transport error, null fields, or missing
//   field), naming the ledger failure. Both halt reasons fail closed.
// - Backward compatibility: equal journals clear without a ledger read, and a
//   manual dispatch with the audited confirmation clears without a ledger read.
//   The ledger read runs only when journals differ and no manual confirmation
//   is present.
//
// Every case runs offline: the fetch stub answers GitHub journal lookups and
// /up reads, and anything unstubbed rejects so no test touches the network.
import { spawnSync } from "node:child_process";
import { describe, expect, it } from "vitest";

const GATE = "ci/production-deploy-gate.mjs";
const STUB = "./ci/test-fetch-stub.mjs";
const TARGET = "a".repeat(40);
const LIVE = "b".repeat(40);
const ORIGIN = "http://stub.invalid";

type JournalEntry = { tag: string; when: number };
type StubEntry = Record<string, unknown>;

function journalBody(entries: JournalEntry[]): StubEntry {
  return {
    content: Buffer.from(JSON.stringify({ entries })).toString("base64"),
    encoding: "base64",
  };
}

function upBody(body: Record<string, unknown>): StubEntry {
  return body;
}

type GateResult = { status: number | null; stdout: string; stderr: string };

function runGate(env: Record<string, string>, stub: StubEntry[]): GateResult {
  const result = spawnSync(process.execPath, ["--import", STUB, GATE, "--check-migrations"], {
    encoding: "utf8",
    timeout: 20_000,
    env: {
      PATH: process.env.PATH ?? "",
      PRODUCTION_ORIGIN: ORIGIN,
      GITHUB_REPOSITORY: "o/r",
      GITHUB_TOKEN: "fixture-only",
      ...env,
      FETCH_STUB_JSON: JSON.stringify(stub),
    },
  });
  return {
    status: result.status,
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? "",
  };
}

const liveJournal = [{ tag: "1000_a", when: 1000 }];
const targetJournal = [
  { tag: "1000_a", when: 1000 },
  { tag: "1001_b", when: 1001 },
  { tag: "1002_c", when: 1002 },
];

function journalStubs(target: JournalEntry[], live: JournalEntry[]): StubEntry[] {
  return [
    { match: `ref=${TARGET}`, body: journalBody(target) },
    { match: `ref=${LIVE}`, body: journalBody(live) },
  ];
}

function migratedUp(ledger: number[]): StubEntry {
  return {
    match: "/up",
    body: upBody({
      revision: { commit: LIVE },
      db: "ok",
      pending_migrations: 0,
      migration_ledger: ledger,
    }),
  };
}

describe("deploy gate auto-promote on migrated production", () => {
  it("clears automatic promotion when the ledger holds every target web entry", () => {
    const result = runGate({ DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "schedule" }, [
      ...journalStubs(targetJournal, liveJournal),
      migratedUp([1000, 1001, 1002]),
    ]);
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/holds all|ledger/i);
  });

  it("clears automatic promotion with harmless extra ledger values", () => {
    const result = runGate(
      { DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "workflow_run" },
      [...journalStubs(targetJournal, liveJournal), migratedUp([1000, 1001, 1002, 9999999999999])],
    );
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/holds all|ledger/i);
  });

  it("halts automatic promotion when the target has migrations the ledger lacks", () => {
    const result = runGate({ DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "schedule" }, [
      ...journalStubs(targetJournal, liveJournal),
      migratedUp([1000]),
    ]);
    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(/1001_b/);
    expect(result.stderr).toMatch(/1002_c/);
  });

  it("halts when a newer foreign row cannot mask a missing web migration", () => {
    const result = runGate({ DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "schedule" }, [
      ...journalStubs(targetJournal, liveJournal),
      migratedUp([1000, 9999999999999]),
    ]);
    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(/1001_b/);
    expect(result.stderr).toMatch(/1002_c/);
  });

  it("halts closed with a ledger reason when the ledger read fails", () => {
    const result = runGate({ DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "schedule" }, [
      ...journalStubs(targetJournal, liveJournal),
      {
        match: "/up",
        body: upBody({
          revision: { commit: LIVE },
          db: "error",
          pending_migrations: null,
          migration_ledger: null,
        }),
      },
    ]);
    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(/ledger/i);
  });

  it("clears manual dispatch on a migrated ledger without operator confirmation", () => {
    const result = runGate(
      { DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "workflow_dispatch" },
      [...journalStubs(targetJournal, liveJournal), migratedUp([1000, 1001, 1002])],
    );
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/holds all|ledger/i);
  });

  it("clears when the live commit and ledger arrive together from /up", () => {
    const result = runGate({ DEPLOY_SHA: TARGET, GITHUB_EVENT_NAME: "schedule" }, [
      {
        match: "/up",
        body: upBody({
          revision: { commit: LIVE },
          db: "ok",
          pending_migrations: 0,
          migration_ledger: [1000, 1001, 1002],
        }),
      },
      ...journalStubs(targetJournal, liveJournal),
    ]);
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/holds all|ledger/i);
  });

  it("clears equal journals without reading the ledger", () => {
    const result = runGate(
      { DEPLOY_SHA: TARGET, LIVE_SHA: LIVE, GITHUB_EVENT_NAME: "schedule" },
      journalStubs(liveJournal, liveJournal),
    );
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/No pending production migrations/);
  });

  it("clears manual confirmation without reading the ledger", () => {
    const result = runGate(
      {
        DEPLOY_SHA: TARGET,
        LIVE_SHA: LIVE,
        GITHUB_EVENT_NAME: "workflow_dispatch",
        MIGRATIONS_APPLIED: "true",
      },
      journalStubs(targetJournal, liveJournal),
    );
    expect(result.status).toBe(0);
    expect(result.stdout).toMatch(/Manual continuation/);
  });
});
